/** Concise widget spec sheet listing each token with its purpose, for tool descriptions. */
export const WIDGET_TOKEN_SHEET: string = "### Widget figure tokens\n- Four-tone palette: --figure-page, --figure-card, --figure-text, --figure-strong, --figure-muted, --figure-paper, --figure-face, --figure-top, --figure-shade-0, --figure-shade-1, --figure-shade-2, --figure-shade-3, --figure-lit-top, --figure-lit-shade, --figure-hi, --figure-mid, --figure-lo, --figure-faint, --figure-lit, --figure-halo, --figure-halo-opacity, --figure-dot, --figure-red, --figure-green, --figure-blue, --figure-weight, --figure-ease, --figure-mono, --figure-lift, --figure-label, --figure-leader, --figure-frame, --figure-label-size.\n- Page/card/text/strong/muted: grounds and explanatory ink. Paper/face/top: opaque solid fills.\n- Shade-0..3: facing tones, darkest to lightest. Lit-top/lit-shade: the selected solid.\n- Hi/mid/lo/faint/lit: subject, structure, base, detail, one selected accent.\n- Halo plus halo-opacity: soft contact shadow. Dot: fasteners. Red/green/blue: signals only.\n- Weight: 0.6px hairlines; ease: cubic-bezier(.32,.72,0,1); mono: system stack; lift: subtle inset/drop shadow.\n- Frame: Fig n top left, mono uppercase title top right, hint bottom left, mono live readout bottom right; legend and true caption below.\n- --chart-1..6 are widget aliases for hi, mid, lo, red, green, blue. Pair colours with labels or patterns.\n- Widget semantic aliases (--background, --foreground, --card, --muted-foreground, --border etc.) use this palette; app UI retains its own colours.\n- Fonts: --font-sans (body), --font-serif (prose), --font-mono (technical labels).\n- Type: --text-xs/sm/base/lg/xl/2xl; --leading-tight/normal. Space: --space-1/2/3/4/5/6/8.\n- Use var(--…) for colours; --stroke-hairline and --figure-frame/label/leader follow the figure layer.\n- Host injects tokens before paint and updates .iso data-theme on theme messages; standalone --light builds still work.\n- Canvas: listen for avenire:themechange and re-read computed tokens from its themed .iso element.";
